function sanitize(raw){const result={};if(!raw||typeof raw!=='object')return result;for(const p of PARTS){const v=raw[p.id];if(!v||typeof v!=='object')continue;const o={};for(const field of p.fields){const x=v[field];if(['text','fill','border'].includes(field)&&good(x))o[field]=String(x).toUpperCase();else if(field==='font'&&Object.prototype.hasOwnProperty.call(FONTS,x))o.font=x;else if(field==='size'&&Number.isFinite(Number(x)))o.size=Math.max(9,Math.min(38,Math.round(Number(x))));}if(Object.keys(o).length)result[p.id]=o;}return result}
